// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const http = require('http');

const routes = [];

function createJsonResponse(res) {
  if (typeof res.json === 'function') {
    return res;
  }

  res.json = (body) => {
    const payload = JSON.stringify(body);
    res.statusCode = res.statusCode || 200;
    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.setHeader('Content-Length', Buffer.byteLength(payload));
    res.end(payload);
  };

  return res;
}

function app(req, res) {
  const url = new URL(req.url, 'http://localhost');
  const route = routes.find((candidate) => (
    candidate.method === req.method && candidate.path === url.pathname
  ));

  createJsonResponse(res);

  if (!route) {
    res.statusCode = 404;
    return res.json({ error: 'Not found' });
  }

  return route.handler(req, res);
}

app.get = (path, handler) => {
  routes.push({ method: 'GET', path, handler });
};

app.listen = (...args) => {
  const server = http.createServer(app);
  return server.listen(...args);
};

